 1	method arrayProduct(a: array<int>, b: array<int>) returns (c: array<int> )
 2	  requires a.Length==b.Length
 3	  ensures c.Length==a.Length
 4	  ensures forall i:: 0 <= i< a.Length==> a[i] * b[i]==c[i]
 5	{
 6	  c:= new int[a.Length];
 7	  var i:=0;
 8	  while i<a.Length
 9	    invariant 0<=i<=a.Length
10	  {
11	    c[i]:=a[i]*b[i];
12	    i:=i+1;
13	  }
14	}

